begin;
create table if not exists public.company_marketing_records (id text primary key, company_account_id uuid not null references public.company_accounts(id) on delete cascade, kind text not null check(kind in ('campaign','template','submission_log')), customer_id text references public.customers(id) on delete set null, payload jsonb not null, revision bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_company_marketing_records_scope on public.company_marketing_records(company_account_id,kind,created_at desc);
alter table public.company_marketing_records enable row level security;
revoke all on public.company_marketing_records from anon,authenticated; grant select on public.company_marketing_records to authenticated;
drop policy if exists "Marketing members read" on public.company_marketing_records;
create policy "Marketing members read" on public.company_marketing_records for select using(exists(select 1 from public.company_accounts where id=company_account_id and owner_user_id=auth.uid()) or public.is_active_company_member(company_account_id));
create or replace function public.marketing_writable(p uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_company_account_writable(p) and (exists(select 1 from public.company_accounts where id=p and owner_user_id=auth.uid()) or public.is_active_company_member(p))$$;
create or replace function public.check_marketing_record_reference() returns trigger language plpgsql security definer set search_path=public as $$begin if new.customer_id is not null and not exists(select 1 from public.customers where id=new.customer_id and company_account_id=new.company_account_id) then raise exception 'Marketing customer_id must belong to the same company_account_id';end if;if tg_op='UPDATE' and new.company_account_id<>old.company_account_id then raise exception 'Marketing company_account_id cannot be changed';end if;return new;end$$;
drop trigger if exists trg_marketing_record_reference on public.company_marketing_records;
create trigger trg_marketing_record_reference before insert or update on public.company_marketing_records for each row execute procedure public.check_marketing_record_reference();
create or replace function public.create_marketing_record(p_id text,p_company uuid,p_kind text,p_customer text,p_payload jsonb) returns public.company_marketing_records language plpgsql security definer set search_path=public as $$declare v public.company_marketing_records;begin if not public.marketing_writable(p_company) then raise exception 'Marketing writes are not allowed for this company';end if;insert into public.company_marketing_records(id,company_account_id,kind,customer_id,payload)values(p_id,p_company,p_kind,p_customer,p_payload)returning * into v;return v;end$$;
create or replace function public.update_marketing_record(p_id text,p_company uuid,p_payload jsonb,p_revision bigint) returns public.company_marketing_records language plpgsql security definer set search_path=public as $$declare v public.company_marketing_records;begin if not public.marketing_writable(p_company) then raise exception 'Marketing writes are not allowed for this company';end if;update public.company_marketing_records set payload=p_payload,revision=revision+1,updated_at=now()where id=p_id and company_account_id=p_company and revision=p_revision returning * into v;if not found then raise exception 'Marketing record changed or no longer exists';end if;return v;end$$;
create or replace function public.delete_marketing_record(p_id text,p_company uuid,p_revision bigint) returns void language plpgsql security definer set search_path=public as $$begin if not public.marketing_writable(p_company) then raise exception 'Marketing writes are not allowed for this company';end if;delete from public.company_marketing_records where id=p_id and company_account_id=p_company and revision=p_revision;if not found then raise exception 'Marketing record changed or no longer exists';end if;end$$;
revoke all on function public.marketing_writable(uuid) from public, anon, authenticated;
revoke all on function public.check_marketing_record_reference() from public, anon, authenticated;
revoke all on function public.create_marketing_record(text,uuid,text,text,jsonb) from public, anon, authenticated;
revoke all on function public.update_marketing_record(text,uuid,jsonb,bigint) from public, anon, authenticated;
revoke all on function public.delete_marketing_record(text,uuid,bigint) from public, anon, authenticated;
grant execute on function public.create_marketing_record(text,uuid,text,text,jsonb),public.update_marketing_record(text,uuid,jsonb,bigint),public.delete_marketing_record(text,uuid,bigint) to authenticated;
commit;
